下面函数返回最后一个小于等于 x 的元素下标（若不存在则返回 -1），该实现是正确的。

```cpp
int findLastLE(const vector<int> &a, int x) {
    int l = 0, r = (int)a.size() - 1, ans = -1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] <= x) { ans = mid; l = mid + 1; }
        else r = mid - 1;
    }
    return ans;
}
```

